mapper.select:
SELECT r.report_id, r.user_id, ru.nickname AS reporter_nickname, r.target_type, r.target_id, CASE r.target_type WHEN 'item' THEN ti.title WHEN 'user' THEN tu.nickname WHEN 'review' THEN tr.content ELSE NULL END AS target_title, r.reason, r.detail, r.status, r.handle_remark, hu.nickname AS handle_by_name, r.handle_time, r.create_time FROM bobo_report r LEFT JOIN bobo_user ru ON ru.user_id = r.user_id LEFT JOIN bobo_user hu ON hu.user_id = r.handle_by LEFT JOIN bobo_item ti ON r.target_type = 'item' AND ti.item_id = r.target_id LEFT JOIN bobo_user tu ON r.target_type = 'user' AND tu.user_id = r.target_id LEFT JOIN bobo_review tr ON r.target_type = 'review' AND tr.review_id = r.target_id
r.del_flag = 0
AND r.target_type = #{q.targetType}
AND r.status = #{q.status}
ORDER BY r.status ASC, r.create_time DESC
